Change(genesis='66602cd0dec37d58d03eec9518ca805a7ac38ea912d2b0c366a0b67b4b9f50b6', deps=(), event=Decided(decision='unclassifiedfailurereaches', at=datetime(2026, 11, 25, 0, 0, 0), actor='assistant', title='A failure the box cannot classify still reaches the owner: a source failing past a bound is shown whatever its class', body="A source that has failed for longer than its bound is shown to the owner whatever the class of its failure, including a class that the box does not know. A provider's refusal is parsed once, at the edge, into a closed sum of codes, so that every code has a case that decides what the owner sees.", rationale='A failure that no class matches would otherwise stay silent, because every card is filed by class. Parsing the refusal once into a closed sum makes the compiler list each place that must handle a new code, and the bound catches whatever the sum does not name.', supersedes=()))